package com.quotexrealvision.ai; import java.util.*; public final class FeatureEngine { public FeatureVector extract(List<Candle> c){FeatureVector f=new FeatureVector();if(c==null||c.size()<8)return f;int n=c.size();double[] cl=new double[n],rg=new double[n];for(int i=0;i<n;i++){cl[i]=c.get(i).close;rg[i]=c.get(i).range();}Candle z=c.get(n-1);double mr=Math.max(1e-9,Maths.mean(Arrays.copyOfRange(rg,Math.max(0,n-8),n)));f.set(0,z.body()/mr).set(1,z.upperWick()/mr).set(2,z.lowerWick()/mr).set(3,z.closePosition()*2-1).set(4,z.range()/mr-1).set(5,(z.close-cl[Math.max(0,n-4)])/mr).set(6,(z.close-cl[Math.max(0,n-8)])/mr);double m3=mean(cl,3),m8=mean(cl,8);f.set(7,(z.close-m3)/mr).set(8,(m3-m8)/mr).set(9,slope(cl,5)/mr).set(10,slope(cl,8)/mr);double hh=Double.NEGATIVE_INFINITY,ll=Double.POSITIVE_INFINITY;for(int i=0;i<n-1;i++){hh=Math.max(hh,c.get(i).high);ll=Math.min(ll,c.get(i).low);}f.set(11,(z.close-hh)/mr).set(12,(z.close-ll)/mr).set(13,z.low<ll&&z.close>ll?1:0).set(14,z.high>hh&&z.close<hh?1:0);if(n>=2){Candle p=c.get(n-2);boolean be=z.bullish&& !p.bullish&&z.open<=p.close&&z.close>=p.open;boolean se=!z.bullish&&p.bullish&&z.open>=p.close&&z.close<=p.open;f.set(15,be?1:se?-1:0);}f.set(16,(z.lowerWick()-z.upperWick())/mr);f.set(17,(z.range()-mean(Arrays.copyOfRange(rg,Math.max(0,n-5),n),5))/mr);f.set(18,Maths.stdev(Arrays.copyOfRange(rg,Math.max(0,n-5),n))/mr);if(n>=3)f.set(19,((cl[n-1]-cl[n-2])-(cl[n-2]-cl[n-3]))/mr);int s=0;boolean d=z.bullish;for(int i=n-1;i>=0;i--){if(c.get(i).bullish==d)s++;else break;}f.set(20,d?s/4.0:-s/4.0).set(21,(z.close-m8)/mr);return f;}private double mean(double[] a,int k){return Maths.mean(Arrays.copyOfRange(a,Math.max(0,a.length-k),a.length));}private double slope(double[] a,int k){k=Math.min(k,a.length);int st=a.length-k;double sx=0,sy=0,sxx=0,sxy=0;for(int i=0;i<k;i++){double x=i,y=a[st+i];sx+=x;sy+=y;sxx+=x*x;sxy+=x*y;}double d=k*sxx-sx*sx;return d==0?0:(k*sxy-sx*sy)/d;}}
